import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"事件 API","description":"","frontmatter":{},"headers":[],"relativePath":"modules/item/events.md","filePath":"modules/item/events.md","lastUpdated":0}`),a={name:`modules/item/events.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="事件-api" tabindex="-1">事件 API <a class="header-anchor" href="#事件-api" aria-label="Permalink to “事件 API”">​</a></h1><p>Item 当前有五个公开事件；源码中不存在 <code>ItemUpdateEvent</code> 或 <code>EquipmentSkillTriggerEvent</code>。事件包为 <code>emaki.jiuwu.craft.item.api.event</code>。</p><table tabindex="0"><thead><tr><th>事件</th><th>触发时机</th><th>线程</th><th>Cancellable</th><th>可修改字段</th><th>取消/结果效果</th><th>runtime 路径</th></tr></thead><tbody><tr><td><code>EmakiItemCreateEvent</code></td><td>factory 已构建 stack、返回调用方前</td><td>global-region owner thread</td><td>是</td><td><code>result</code>，必须非 null</td><td>取消丢弃结果；公开 <code>create</code> 返回 <code>CANCELLED</code></td><td>进入 <code>EmakiItemFactory</code> 且当前拥有 global region 的创建路径</td></tr><tr><td><code>ItemRepairEvent</code></td><td>修复校验后、扣费和恢复耐久前</td><td>玩家 owner thread</td><td>是</td><td><code>restoreAmount</code></td><td>取消不扣费、不修复；<code>&lt;=0</code> 也抑制修复</td><td>材料与经济修复 service，包括公开 <code>repair()</code> 的经济路径</td></tr><tr><td><code>ItemSetBonusChangeEvent</code></td><td>active set count 实际改变后</td><td>玩家 owner thread</td><td>否</td><td>无</td><td>post 通知，不可回滚</td><td>装备套装刷新，每个变化 set id 一次</td></tr><tr><td><code>ItemStateChangeEvent</code></td><td>item state 变更已提交后</td><td>执行该次变更的 owner thread</td><td>否</td><td>无</td><td>post 通知，不可回滚</td><td><code>state()</code> 的 <code>set</code>/<code>add</code>/<code>remove</code> 提交路径</td></tr><tr><td><code>ItemStateThresholdEvent</code></td><td>数值 item state 变更跨过已配置阈值后</td><td>执行该次变更的 owner thread</td><td>否</td><td>无</td><td>post 通知，不可回滚</td><td>提交并完成 once 阈值重置记账之后，每跨过一个阈值一次</td></tr></tbody></table><p>当前 factory 创建事件的 player 为 null。若不拥有 global region，runtime 会跳过创建事件并仍返回分离构建结果，因此它不是所有 ItemStack 创建的完整审计流。Migration 和普通 refresh 没有独立公开事件。<code>ItemSetBonusChangeEvent</code> 是 post 事件，不能取消。</p><p><code>ItemStateChangeEvent</code> 暴露 <code>getItem()</code>（克隆件）、<code>getMutation()</code>、<code>getHolder()</code>（无已知持有者时为 null）以及从 mutation 转发的 <code>getKey()</code>、<code>getOldValue()</code>、<code>getNewValue()</code>、<code>getDelta()</code>。</p><p><code>ItemStateThresholdEvent</code> 暴露 <code>getItem()</code>、<code>getHolder()</code>、<code>getKey()</code>、<code>getOldValue()</code>、<code>getNewValue()</code>、<code>getThreshold()</code>、<code>getThresholdId()</code>、<code>getDirection()</code>（<code>UP</code>/<code>DOWN</code>）、<code>isOnce()</code> 与 <code>isRearmed()</code>。它只覆盖配置了阈值的数值字段（<code>INTEGER</code>、<code>LONG</code>、<code>DOUBLE</code>）；向上跨越按阈值升序、向下跨越按降序各派发一次。被拒绝或未改变的变更、保留的 <code>meta.</code> 元数据键、<code>BOOLEAN</code> 与 <code>STRING</code> 字段、未配置阈值的数值字段、新旧值处于同一侧、仍处于 latch 状态的 once 阈值，以及重建保留原样回写的状态都不会派发。</p>`,6)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};